package com.masrofy.ai;
import android.app.*;import android.os.*;import android.graphics.Color;import android.widget.*;import java.util.*;
public class MainActivity extends Activity{double in=0,ex=0; TextView b,s; public void onCreate(Bundle x){super.onCreate(x);home();} TextView t(String x,int z){TextView v=new TextView(this);v.setText(x);v.setTextSize(z);v.setPadding(20,20,20,20);return v;} Button bt(String x,final Runnable r){Button b=new Button(this);b.setText(x);b.setOnClickListener(v->r.run());return b;} void home(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(24,24,24,80);TextView h=t("مِصروفي AI",28);h.setTextColor(Color.rgb(10,174,120));l.addView(h);b=t("الرصيد الحالي\n"+m(in-ex),25);l.addView(b);s=t("الدخل: "+m(in)+"\nالمصروفات: "+m(ex)+"\nالادخار: "+m(Math.max(0,in-ex)),17);l.addView(s);l.addView(bt("💰 إضافة دخل",()->add(true)));l.addView(bt("🧾 إضافة مصروف",()->add(false)));l.addView(bt("🤖 تحليل ذكي",()->analysis()));setContentView(new ScrollView(this){{addView(l);}});} void add(boolean income){EditText e=new EditText(this);e.setInputType(2);e.setHint("المبلغ بالجنيه");new AlertDialog.Builder(this).setTitle(income?"إضافة دخل":"إضافة مصروف").setView(e).setPositiveButton("حفظ",(d,w)->{try{double v=Double.parseDouble(e.getText().toString());if(income)in+=v;else ex+=v;home();}catch(Exception q){}}).setNegativeButton("إلغاء",null).show();} void analysis(){new AlertDialog.Builder(this).setTitle("🤖 التحليل الذكي").setMessage(ex==0?"أضف مصروفات أولًا.":"مصروفاتك: "+m(ex)+"\nنسبة الإنفاق: "+(in>0?Math.round(ex/in*100):0)+"%\n\n💡 حاول خفض أكبر بنود الإنفاق تدريجيًا.").setPositiveButton("حسنًا",null).show();} String m(double n){return String.format(Locale.US,"%.0f ج.م",n);}}
